/// <summary>
/// Gates document attachments on a Defender for Storage malware verdict and on agreement between
/// a file's binary signature and the extension it claims.
/// </summary>
public final class FOSecureDocuEventHandler
{
}

Method.Source:
/// <summary>
/// Scans a document attachment when it is uploaded, previewed or downloaded.
/// </summary>
/// <param name = "_docuRef">The attachment being scanned.</param>
/// <param name = "_validationResult">Rejected when the file must not be used.</param>
/// <remarks>
/// Content validation decides first. It reads bytes that are already to hand, where the malware
/// scan uploads the file to the quarantine container and waits on Defender; a file the content
/// check rejects is never submitted, and the reason is recorded against it instead.
/// </remarks>
[SubscribesTo(classStr(Docu), staticDelegateStr(Docu, delegateScanDocument))]
public static void Docu_delegateScanDocument(DocuRef _docuRef, EventHandlerRejectResult _validationResult)
{
    if (!_docuRef || !_docuRef.isValueAttached())
    {
        return;
    }

    DocuValue docuValue = _docuRef.docuValue();

    if (!docuValue)
    {
        return;
    }

    DocuParameters parameters = DocuParameters::find();

    boolean inspectContent = parameters.FOSecureValidateAttachmentContent == NoYes::Yes;

    boolean submitForMalwareScan = parameters.FOSecureScanAttachmentsForMalware == NoYes::Yes
        && docuValue.FileId != emptyGuid()
        && FOSecureAttachmentScan::findByFileId(docuValue.FileId).needsSubmission();

    // A recorded verdict answers preview and download without reading a byte.
    if (inspectContent
        && FOSecureContentGate::applyRecordedVerdict(docuValue, parameters, _validationResult))
    {
        if (_validationResult.isRejected())
        {
            FOSecureDocuEventHandler::noteContentBlock(_docuRef, docuValue, submitForMalwareScan);

            return;
        }

        inspectContent = false;
    }

    if (!submitForMalwareScan
        && FOSecureMalwareScanManager::rejectIfUnsafe(docuValue, _validationResult))
    {
        return;
    }

    if (submitForMalwareScan || inspectContent)
    {
        FOSecureDocuEventHandler::scanAttachment(
            _docuRef, docuValue, parameters, _validationResult, submitForMalwareScan, inspectContent);
    }

    if (submitForMalwareScan && !_validationResult.isRejected())
    {
        FOSecureMalwareScanManager::rejectIfMalicious(docuValue, _validationResult);
    }
}

/// <summary>
/// Opens the attachment once and runs whichever content checks are required.
/// </summary>
/// <param name = "_docuRef">The attachment being scanned.</param>
/// <param name = "_docuValue">The stored file behind the reference.</param>
/// <param name = "_parameters">Document management parameters.</param>
/// <param name = "_validationResult">Rejected when the file must not be used.</param>
/// <param name = "_submitForMalwareScan">Whether to send the content to the quarantine container.</param>
/// <param name = "_inspectContent">Whether to identify the content and look for active content.</param>
private static void scanAttachment(
    DocuRef                  _docuRef,
    DocuValue                _docuValue,
    DocuParameters           _parameters,
    EventHandlerRejectResult _validationResult,
    boolean                  _submitForMalwareScan,
    boolean                  _inspectContent)
{
    FOSecureContentWindow window;
    FOSecureFileHash      contentSha256;

    try
    {
        using (System.IO.Stream attachmentStream = DocumentManagement::getAttachmentStream(_docuRef))
        {
            if (attachmentStream == null)
            {
                FOSecureDocuEventHandler::noteNotScanned(
                    _docuRef,
                    _docuValue,
                    _submitForMalwareScan,
                    FOSecureMalwareScanState::Unavailable,
                    'attachment content could not be read');

                return;
            }

            if (_inspectContent)
            {
                window = FOSecureContentWindow::fromStream(
                    attachmentStream,
                    FOSecureContentGate::windowBytes(_parameters),
                    FOSecureContentConstants::TailBytes);

                if (!window.isEmpty())
                {
                    contentSha256 = FOSecureDocuEventHandler::contentHash(attachmentStream);

                    FOSecureContentGate::inspectRecordAndEnforce(
                        _docuRef, _docuValue, window, contentSha256, _parameters, _validationResult);

                    if (_validationResult.isRejected())
                    {
                        // The cheap check has already decided; no quarantine round trip is owed.
                        FOSecureDocuEventHandler::noteContentBlock(
                            _docuRef, _docuValue, _submitForMalwareScan);

                        return;
                    }
                }
            }

            if (_submitForMalwareScan)
            {
                FOSecureMalwareScanManager::submitAttachment(_docuRef, _docuValue, attachmentStream);
            }
        }
    }
    catch (Exception::CLRError)
    {
        FOSecureDocuEventHandler::noteNotScanned(
            _docuRef, _docuValue, _submitForMalwareScan,
            FOSecureMalwareScanState::Unavailable, 'attachment could not be scanned');

        exceptionTextFallThrough();
    }
    catch (Exception::Error)
    {
        FOSecureDocuEventHandler::noteNotScanned(
            _docuRef, _docuValue, _submitForMalwareScan,
            FOSecureMalwareScanState::Unavailable, 'attachment could not be scanned');

        exceptionTextFallThrough();
    }
}

/// <summary>
/// Computes the SHA-256 of the whole attachment, leaving the stream position as it found it.
/// </summary>
/// <param name = "_content">The open attachment stream.</param>
/// <returns>The hash, or empty when the stream cannot be rewound.</returns>
private static FOSecureFileHash contentHash(System.IO.Stream _content)
{
    FOSecureFileHash hash;
    int64            originalPosition;

    if (_content == null || !_content.CanRead || !_content.CanSeek)
    {
        return hash;
    }

    try
    {
        originalPosition = _content.Position;
    }
    catch (Exception::CLRError)
    {
        // Disposed or unusable: nothing to restore, and nothing to hash.
        return hash;
    }

    try
    {
        _content.Position = 0;
        hash = FOSecureMalwareScanClient::computeSha256(_content);
    }
    catch (Exception::CLRError)
    {
        exceptionTextFallThrough();
    }
    catch (Exception::Error)
    {
        exceptionTextFallThrough();
    }
    finally
    {
        try
        {
            _content.Position = originalPosition;
        }
        catch (Exception::CLRError)
        {
            exceptionTextFallThrough();
        }
    }

    return hash;
}

/// <summary>
/// Records that content validation stopped the file before it could be submitted for scanning.
/// </summary>
/// <param name = "_docuRef">The attachment being scanned.</param>
/// <param name = "_docuValue">The stored file behind the reference.</param>
/// <param name = "_submitWasDue">Whether a submission was owed; nothing is recorded otherwise.</param>
private static void noteContentBlock(DocuRef _docuRef, DocuValue _docuValue, boolean _submitWasDue)
{
    FOSecureDocuEventHandler::noteNotScanned(
        _docuRef,
        _docuValue,
        _submitWasDue,
        FOSecureMalwareScanState::NotScanned,
        'blocked by content validation; not submitted for scanning');
}

/// <summary>
/// Leaves a scan row behind for a file that was due a scan and did not get one.
/// </summary>
/// <param name = "_docuRef">The attachment being scanned.</param>
/// <param name = "_docuValue">The stored file behind the reference.</param>
/// <param name = "_submitWasDue">Whether a submission was owed; nothing is recorded otherwise.</param>
/// <param name = "_state">The state explaining why no verdict exists.</param>
/// <param name = "_detail">What stopped the submission.</param>
private static void noteNotScanned(
    DocuRef                  _docuRef,
    DocuValue                _docuValue,
    boolean                  _submitWasDue,
    FOSecureMalwareScanState _state,
    FOSecureScanDetail       _detail)
{
    if (!_submitWasDue)
    {
        return;
    }

    try
    {
        FOSecureMalwareScanManager::recordNotSubmitted(_docuRef, _docuValue, _state, _detail);
    }
    catch (Exception::CLRError)
    {
        // Failing to write the log must never be the reason the scan itself fails.
        exceptionTextFallThrough();
    }
    catch (Exception::Error)
    {
        exceptionTextFallThrough();
    }
}
